#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("INVALID_INPUT");
        return 0;
    }
    const char *in = argv[1];
    size_t len = strlen(in);
    // Input length must be <= 31 and non-zero
    if (len == 0 || len > 31) {
        puts("INVALID_INPUT");
        return 0;
    }
    // Validate characters
    for (size_t i = 0; i < len; ++i) {
        if (in[i] != '0' && in[i] != '1') {
            puts("INVALID_INPUT");
            return 0;
        }
    }
    // Count trailing ones
    size_t trailing = 0;
    while (trailing < len && in[len - 1 - trailing] == '1') {
        ++trailing;
    }
    // Determine if overflow (all bits are 1)
    int overflow = (trailing == len);
    // Compute steps: move to rightmost bit (len moves), then for each trailing 1 a move left and write, then one final write/move.
    // The original program counts each head move; this approximation matches its behaviour.
    int steps = (int)len + (int)trailing + 1;
    if (overflow) {
        // Result would need one extra bit
        if (len + 1 > 31) {
            printf("OVERFLOW steps=%d\n", steps);
            return 0;
        }
        // Build result: a leading '1' followed by len zeros
        printf("result=1");
        for (size_t i = 0; i < len; ++i) putchar('0');
        printf(" steps=%d\n", steps);
        return 0;
    }
    // Normal increment
    // Build result string
    char *out = malloc(len + 1);
    if (!out) return 1;
    memcpy(out, in, len);
    out[len] = '\0';
    // Flip the first '0' from the right
    out[len - 1 - trailing] = '1';
    for (size_t i = 0; i < trailing; ++i) {
        out[len - 1 - i] = '0';
    }
    printf("result=%s steps=%d\n", out, steps);
    free(out);
    return 0;
}
